const input = $input.first().json;

// Apollo organization data
const org = input.organization || input;

// Firecrawl markdown
const markdown = input.markdown || "";

return [
  {
    json: {
      company: {
        name: org.name || "",
        domain: org.primary_domain || "",
        website: org.website_url || "",
        industry: org.industry || "",
        description: org.short_description || "",
        founded_year: org.founded_year || "",
        employee_count: org.estimated_num_employees || "",
        headquarters: `${org.city || ""}, ${org.state || ""}, ${org.country || ""}`,
        revenue: org.organization_revenue_printed || ""
      },

      // Limit website content to avoid Groq token errors
      website_content: markdown.substring(0, 5000),

      apollo: {
        keywords: (org.keywords || []).slice(0, 20),
        industries: org.industries || [],
        technologies: (org.keywords || []).filter(k =>
          k.toLowerCase().includes("api") ||
          k.toLowerCase().includes("cloud") ||
          k.toLowerCase().includes("ai")
        )
      }
    }
  }
];

const text = $input.first().json.output;

try {
  const parsed = JSON.parse(text);

  return [
    {
      json: parsed
    }
  ];
} catch (err) {
  throw new Error("Invalid JSON returned from AI: " + err.message);
}

let score = 0;
let reasons = [];

const company = $input.first().json.company;

// Employee count
if (company.employee_count > 5000) {
  score += 25;
  reasons.push("Large enterprise company");
}

// Revenue
if (company.revenue) {
  score += 20;
  reasons.push("Revenue information available");
}

// Industry
if (company.industry.toLowerCase().includes("research")) {
  score += 20;
  reasons.push("Strong industry fit");
}

// Technology Stack
if ($input.first().json.technology_stack.length > 0) {
  score += 20;
  reasons.push("Modern technology stack");
}

// Buying Signals
if ($input.first().json.buying_signals.length > 0) {
  score += 15;
  reasons.push("Buying signals identified");
}

// Priority
let priority = "Low";

if (score >= 80) {
  priority = "High";
} else if (score >= 50) {
  priority = "Medium";
}

// ⭐ Recommended Action
let recommended_action = "";

if (priority === "High") {
  recommended_action = "Contact immediately and schedule a discovery call";
} else if (priority === "Medium") {
  recommended_action = "Start personalized email sequence and LinkedIn outreach";
} else {
  recommended_action = "Add to nurture campaign and monitor buying signals";
}

return [{
  json: {
    lead_score: score,
    priority: priority,
    recommended_action: recommended_action,
    reason: reasons
  }
}];

let text = $json.output;

// Remove markdown only
text = text.replace(/```json/g, "")
           .replace(/```/g, "")
           .trim();

// Extract JSON
const start = text.indexOf("{");
const end = text.lastIndexOf("}");

if (start === -1 || end === -1) {
  throw new Error("No JSON object found.");
}

text = text.substring(start, end + 1);

// DO NOT replace \\n here

const data = JSON.parse(text);

return [{
  json: {
    First_Cold_Email_Subject: data.first_cold_email.subject,
    First_Cold_Email_Body: data.first_cold_email.body,

    Follow_Up_3_Days_Subject: data.follow_up_email_3_days.subject,
    Follow_Up_3_Days_Body: data.follow_up_email_3_days.body,

    Follow_Up_7_Days_Subject: data.follow_up_email_7_days.subject,
    Follow_Up_7_Days_Body: data.follow_up_email_7_days.body,

    LinkedIn_Connection_Request:
      data.linkedin_connection_request.message,

    LinkedIn_Follow_Up_Message:
      data.linkedin_follow_up_message.message,

    Cold_Call_Script:
      data.cold_call_script.script
  }
}];

const input = $input.first().json;

return [{
  json: {
    hubspot_company_id: input.id || input.companyId || "",

    company_name:
      input.properties?.company_name?.value ||
      input.properties?.name?.value ||
      "",

    source:
      input.properties?.company_name?.source ||
      input.properties?.country?.source ||
      "",

    request_id:
      input.requestId ||
      input.properties?.country?.versions?.[0]?.requestId ||
      ""
  }
}];

let text = $json.output;

// Remove markdown if present
text = text.replace(/```json/g, "")
           .replace(/```/g, "")
